"""Self-contained HTML for the mailbox sidecar."""

MAILBOX_LOGIN_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mailbox API Login</title><style>
:root{--bg:#111317;--panel:#1a1e24;--line:#303844;--text:#edf2f7;--muted:#9ba9ba;--accent:#18b6a4;--danger:#ef6b73}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.login{width:min(360px,calc(100% - 32px));padding:28px;border:1px solid var(--line);border-radius:8px;background:var(--panel)}h1{font-size:20px;margin:0 0 6px}p{color:var(--muted);margin:0 0 20px}label{display:block;font-size:12px;color:var(--muted);margin-bottom:6px}input{width:100%;background:#101419;border:1px solid var(--line);border-radius:5px;padding:10px;color:var(--text);font:inherit}button{width:100%;margin-top:14px;border:0;border-radius:5px;padding:10px;background:var(--accent);color:#06231f;font-weight:700;cursor:pointer}.err{min-height:18px;color:var(--danger);margin-top:10px;font-size:12px}</style></head>
<body><main class="login"><h1>Mailbox API</h1><p>收件与客户取码管理</p><form id="login"><label for="password">管理员密码</label><input id="password" type="password" autocomplete="current-password" required autofocus><button>登录</button><div id="error" class="err"></div></form></main><script>
document.getElementById('login').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:password.value})});if(r.ok)location='/';else error.textContent='密码错误或服务不可用';});
</script></body></html>"""


def customer_mailbox_page(api_url_json: str) -> str:
    """Render a customer-facing browser page without exposing mailbox metadata."""
    return r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenAI 验证码</title><style>
:root{--bg:#101419;--panel:#1a2028;--line:#34404e;--text:#eef4fa;--muted:#a4b2c2;--accent:#4fd1b5;--warn:#e7ba5e}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;background:var(--bg);color:var(--text);font:15px system-ui,sans-serif}.box{width:min(460px,100%);border:1px solid var(--line);border-radius:7px;background:var(--panel);padding:24px}h1{font-size:18px;margin:0 0 20px}.code{font:600 34px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:3px;color:var(--accent);min-height:45px}.subject{margin-top:16px;line-height:1.5}.time,.status{font-size:12px;color:var(--muted);margin-top:8px}.status{color:var(--warn)}</style></head><body><main class="box"><h1>OpenAI 验证码</h1><div id="code" class="code">正在获取</div><div id="subject" class="subject"></div><div id="time" class="time"></div><div id="status" class="status"></div></main><script>
let endpoint=__MAILBOX_ENDPOINT__,timer;const code=document.getElementById('code'),subject=document.getElementById('subject'),time=document.getElementById('time'),status=document.getElementById('status');
function countdown(prefix){clearInterval(timer);let seconds=10;const render=()=>status.textContent=prefix+'，'+seconds+' 秒后刷新';render();timer=setInterval(()=>{seconds-=1;if(seconds<=0){clearInterval(timer);refresh()}else render()},1000)}async function refresh(){try{const r=await fetch(endpoint,{cache:'no-store'});endpoint=endpoint.replace('&sync=1','&sync=0');const d=await r.json();if(d.success){code.textContent=d.code;subject.textContent=d.subject;time.textContent=new Date(d.received_at).toLocaleString();countdown('下次更新');return}code.textContent=d.message||'最近 10 分钟没有新的 OpenAI 验证码';subject.textContent='';time.textContent='';countdown(d.message||'最近 10 分钟没有新的 OpenAI 验证码')}catch(_){code.textContent='暂时无法获取';countdown('暂时无法获取')}}refresh();
</script></body></html>""".replace("__MAILBOX_ENDPOINT__", api_url_json)


MAILBOX_DASHBOARD_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mailbox API</title><style>
:root{--bg:#111317;--panel:#1a1e24;--panel2:#15191e;--line:#303844;--text:#edf2f7;--muted:#9ba9ba;--accent:#18b6a4;--blue:#4e9de6;--warn:#f2b84b;--danger:#ef6b73;--good:#6ed4a5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.shell{width:min(1380px,calc(100% - 32px));margin:auto}.top{min-height:68px;display:flex;align-items:center;gap:16px;border-bottom:1px solid var(--line);margin-bottom:20px}.brand{font-size:20px;font-weight:700}.brand span{color:var(--accent)}.stats{display:flex;gap:14px;margin-left:auto;color:var(--muted);font-size:12px}.stats b{color:var(--text);font-size:15px}.logout{margin-left:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:16px}.wide{margin-bottom:16px}h2{font-size:15px;margin:0 0 14px}h3{font-size:13px;margin:18px 0 10px;color:var(--muted)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.form-grid .full{grid-column:1/-1}label{display:block;font-size:11px;color:var(--muted);margin-bottom:4px}input,select{width:100%;min-height:34px;border:1px solid var(--line);border-radius:4px;background:#101419;color:var(--text);padding:7px;font:inherit}input[type=checkbox]{width:auto;min-height:auto;padding:0}button{min-height:32px;border:1px solid var(--line);border-radius:4px;background:#232b34;color:var(--text);font:inherit;padding:6px 10px;cursor:pointer}button:hover{border-color:var(--blue)}button.primary{background:var(--accent);border-color:var(--accent);color:#06231f;font-weight:700}button.small{min-height:28px;padding:4px 7px;font-size:12px}.actions{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.hint{font-size:12px;color:var(--muted);margin:8px 0 0}.scroll{overflow:auto;border:1px solid var(--line);border-radius:5px}table{border-collapse:collapse;width:100%;min-width:960px;font-size:12px}th,td{padding:9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}th{color:var(--muted);font-weight:600;background:var(--panel2);white-space:nowrap}tr:last-child td{border-bottom:0}.state{font-size:11px;font-weight:700}.state.ok{color:var(--good)}.state.bad{color:var(--danger)}.state.wait{color:var(--warn)}.notice{min-height:18px;color:var(--warn);font-size:12px;margin:0 0 10px}.toolbar{display:flex;gap:8px;align-items:end;flex-wrap:wrap;margin-bottom:12px}.toolbar>div{min-width:150px}.toolbar label{margin-bottom:3px}.pager{display:flex;gap:8px;align-items:center;justify-content:flex-end;margin-top:10px;color:var(--muted);font-size:12px}.token{display:none;position:fixed;inset:0;background:#0009;place-items:center;padding:16px;z-index:5}.token.show{display:grid}.token-box{width:min(720px,100%);max-height:calc(100vh - 32px);overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:20px}.token-box pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#101419;padding:10px;border:1px solid var(--line);border-radius:4px;color:var(--good)}.token-head{display:flex;justify-content:space-between;align-items:center}.hidden{display:none}@media(max-width:760px){.shell{width:min(100% - 20px,1380px)}.top{align-items:flex-start;padding:14px 0;flex-wrap:wrap}.stats{margin-left:0;order:3;width:100%}.grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}}
</style></head><body><div class="shell"><header class="top"><div class="brand">Mailbox <span>API</span></div><div class="stats"><span>别名 <b id="aliasCount">0</b></span><span>已启用 <b id="activeCount">0</b></span><span>已导出 <b id="exportedCount">0</b></span><span>Profile <b id="profileCount">0</b></span></div><button class="small logout" onclick="logout()">退出</button></header>
<div id="notice" class="notice"></div><section class="grid"><div class="panel"><h2>新增收件 Profile</h2><form id="profileForm"><div class="form-grid"><div><label>邮箱服务</label><select id="preset" name="preset" onchange="presetChanged()"><option value="gmail">Gmail</option><option value="126">126 Mail</option><option value="163">163 Mail</option><option value="icloud">iCloud Mail</option><option value="custom">自定义 IMAP</option></select></div><div><label>IMAP 账号 / 最终转发邮箱</label><input name="email" type="email" required></div><div class="full"><label>IMAP App 密码 / 授权码</label><input name="imap_password" type="password" required></div><div><label>网络路线</label><select name="network_mode"><option value="direct">直连</option><option value="socks5">SOCKS5 / SOCKS5h</option><option value="http_connect">HTTP CONNECT</option></select></div><div><label>代理地址（仅非直连）</label><input name="proxy_url" placeholder="socks5h://127.0.0.1:1080"></div><div id="customHost" class="hidden"><label>IMAP Host</label><input name="imap_host" value=""></div><div id="customPort" class="hidden"><label>端口</label><input name="imap_port" value="993" type="number"></div><div id="customUser" class="hidden"><label>IMAP 用户名</label><input name="imap_username" value=""></div><div id="customFolder" class="hidden"><label>文件夹</label><input name="folder" value="INBOX"></div></div><div class="actions" style="margin-top:12px"><button class="primary">保存 Profile</button></div></form><p class="hint">Gmail、126、163 和 iCloud 已预设服务器参数，只需填写账号与 App 密码。</p></div><div class="panel"><h2>收件与清理</h2><div class="form-grid"><div><label>邮件保留天数</label><input id="retentionDays" type="number" min="1" max="90"></div><div class="actions"><button type="button" onclick="saveRetention()">保存保留期</button></div></div><h3>Profile 同步</h3><div id="profiles" class="scroll"></div><p class="hint">后台每分钟同步一次；客户请求没有新码时，会对对应 Profile 发起一次即时补同步。</p></div></section>
<section class="panel wide"><h2>Apple 主账号默认转发映射</h2><div id="accounts" class="scroll"></div><p class="hint">此映射只决定本地到哪个最终转发邮箱收件，不会修改 Apple 官网设置。</p></section>
<section class="panel wide"><h2>HME 销售与客户取件页</h2><div class="toolbar"><div><label>Apple 主账号</label><select id="filterSource" onchange="applyFilters()"></select></div><div><label>导出状态</label><select id="filterExported" onchange="applyFilters()"><option value="unexported">未导出</option><option value="exported">已导出</option><option value="all">全部</option></select></div><div class="actions"><button class="primary" type="button" onclick="batchExport()">批量签发并导出</button></div></div><div id="aliases" class="scroll"></div><div id="pager" class="pager"></div><p class="hint">批量导出格式：HME----客户取件网页。每页最多 100 条；签发后的链接仅在本次导出中可见。</p></section></div>
<div id="tokenModal" class="token" role="dialog"><div class="token-box"><div class="token-head"><h2 id="tokenTitle">客户取件链接</h2><button type="button" onclick="closeToken()">关闭</button></div><pre id="tokenContent"></pre><button class="primary" type="button" onclick="copyToken()">复制内容</button></div></div>
<script>
let state={profiles:[],accounts:[],aliases:[],summary:{},pagination:{page:1,pages:1,total:0}};let filters={page:1,source_account:'',exported:'unexported'};const selected=new Set();const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({success:false,error:'Invalid response'}));if(!r.ok)throw Error(data.error||data.message||'Request failed');return data}
function profileOptions(selectedId,empty=true){return (empty?'<option value="">使用主账号默认</option>':'')+state.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===selectedId?'selected':''}>${esc(p.label)} · ${esc(p.email)}</option>`).join('')}
function presetChanged(){const custom=$('preset').value==='custom';for(const id of ['customHost','customPort','customUser','customFolder'])$(id).classList.toggle('hidden',!custom)}
function renderFilters(){const source=$('filterSource');source.innerHTML='<option value="">全部主账号</option>'+state.accounts.map(a=>`<option value="${esc(a.source_account)}" ${a.source_account===filters.source_account?'selected':''}>${esc(a.source_account)} (${a.alias_count})</option>`).join('');$('filterExported').value=filters.exported}
function render(){const s=state.summary||{};$('aliasCount').textContent=s.total||0;$('activeCount').textContent=s.active||0;$('exportedCount').textContent=s.exported||0;$('profileCount').textContent=state.profiles.length;$('retentionDays').value=state.retention_days;renderFilters();
$('profiles').innerHTML=`<table><thead><tr><th>Profile</th><th>收件邮箱</th><th>路线</th><th>最后同步</th><th>状态</th><th></th></tr></thead><tbody>${state.profiles.map(p=>`<tr><td>${esc(p.label)}</td><td>${esc(p.email)}</td><td>${esc(p.network_mode)}</td><td>${esc(p.last_sync_at||'尚未同步')}</td><td class="${p.last_error?'state bad':'state ok'}">${esc(p.last_error||'正常')}</td><td><button class="small" type="button" onclick="syncProfile('${esc(p.id)}')">立即同步</button> <button class="small" type="button" onclick="inspectProfile('${esc(p.id)}')">最近收件</button></td></tr>`).join('')||'<tr><td colspan="6">尚未配置收件 Profile</td></tr>'}</tbody></table>`;
$('accounts').innerHTML=`<table><thead><tr><th>Apple 主账号</th><th>HME 数量</th><th>默认最终转发邮箱</th><th></th></tr></thead><tbody>${state.accounts.map(a=>`<tr><td>${esc(a.source_account)}</td><td>${a.alias_count}</td><td><select id="acc_${esc(a.source_account)}">${profileOptions(a.profile_id,false)||'<option value="">请先创建 Profile</option>'}</select></td><td><button class="small" type="button" onclick="saveAccount('${esc(a.source_account)}')">保存</button></td></tr>`).join('')||'<tr><td colspan="4">尚未从 HME 历史发现账号</td></tr>'}</tbody></table>`;
$('aliases').innerHTML=`<table><thead><tr><th><input id="selectAll" type="checkbox" onchange="togglePageSelection(this.checked)"></th><th>HME</th><th>来源账号</th><th>最终转发覆盖</th><th>客户备注</th><th>到期</th><th>取件</th><th>导出状态</th><th>操作</th></tr></thead><tbody>${state.aliases.map(a=>`<tr><td><input type="checkbox" data-email="${esc(a.email)}" ${selected.has(a.email)?'checked':''} onchange="toggleSelection(this)"></td><td>${esc(a.email)}</td><td>${esc(a.source_account)}</td><td><select id="alias_${esc(a.email)}">${profileOptions(a.profile_id)}</select></td><td><input id="note_${esc(a.email)}" value="${esc(a.buyer_note)}" placeholder="订单 / 客户"></td><td><input id="exp_${esc(a.email)}" value="${esc(a.expires_at)}" placeholder="RFC3339"></td><td><label class="state ${a.api_active?'ok':'wait'}"><input id="active_${esc(a.email)}" type="checkbox" ${a.api_active?'checked':''}> ${a.api_active?'启用':'停用'}</label></td><td class="${a.exported_at?'state ok':'state wait'}">${a.exported_at?esc(a.exported_at):'未导出'}</td><td><button class="small" type="button" onclick="saveAlias('${esc(a.email)}')">保存</button> <button class="small primary" type="button" onclick="issueToken('${esc(a.email)}')">${a.public_id?'轮换链接':'签发链接'}</button></td></tr>`).join('')||'<tr><td colspan="9">没有符合筛选条件的 HME</td></tr>'}</tbody></table>`;const all=state.aliases.length>0&&state.aliases.every(a=>selected.has(a.email));$('selectAll').checked=all;
const p=state.pagination;$('pager').innerHTML=`<button class="small" type="button" ${p.page<=1?'disabled':''} onclick="setPage(${p.page-1})">上一页</button><span>第 ${p.page} / ${p.pages} 页，共 ${p.total} 条</span><button class="small" type="button" ${p.page>=p.pages?'disabled':''} onclick="setPage(${p.page+1})">下一页</button>`}
async function load(){try{const q=new URLSearchParams({page:String(filters.page),source_account:filters.source_account,exported:filters.exported});state=await api('/api/admin/status?'+q);filters.page=state.pagination.page;$('notice').textContent='';render()}catch(e){$('notice').textContent=e.message;if(String(e.message).includes('login'))location='/login'}}
function applyFilters(){filters.source_account=$('filterSource').value;filters.exported=$('filterExported').value;filters.page=1;selected.clear();load()}function setPage(page){filters.page=page;selected.clear();load()}function toggleSelection(input){if(input.checked)selected.add(input.dataset.email);else selected.delete(input.dataset.email);$('selectAll').checked=state.aliases.length>0&&state.aliases.every(a=>selected.has(a.email))}function togglePageSelection(checked){state.aliases.forEach(a=>checked?selected.add(a.email):selected.delete(a.email));render()}
async function saveAccount(account){await api('/api/admin/accounts/'+encodeURIComponent(account)+'/profile',{method:'POST',body:JSON.stringify({profile_id:$('acc_'+account).value})});$('notice').textContent='主账号映射已保存'}
async function saveAlias(email){await api('/api/admin/aliases/'+encodeURIComponent(email)+'/profile',{method:'POST',body:JSON.stringify({profile_id:$('alias_'+email).value})});await api('/api/admin/aliases/'+encodeURIComponent(email)+'/sales',{method:'POST',body:JSON.stringify({api_active:$('active_'+email).checked,buyer_note:$('note_'+email).value,expires_at:$('exp_'+email).value})});const item=state.aliases.find(a=>a.email===email);if(item)item.api_active=$('active_'+email).checked;$('notice').textContent='别名设置已保存'}
function showToken(title,content){$('tokenTitle').textContent=title;$('tokenContent').textContent=content;$('tokenModal').classList.add('show')}function closeToken(){$('tokenModal').classList.remove('show')}function copyToken(){navigator.clipboard.writeText($('tokenContent').textContent)}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeToken()});
async function issueToken(email){try{const d=await api('/api/admin/aliases/'+encodeURIComponent(email)+'/token',{method:'POST'});const item=state.aliases.find(a=>a.email===email);if(item){item.public_id=d.public_id;item.exported_at=d.exported_at;item.api_active=true;render()}showToken('客户取件链接',email+'----'+d.page_url)}catch(e){$('notice').textContent=e.message}}
async function batchExport(){const emails=[...selected];if(!emails.length){$('notice').textContent='请先选择要导出的 HME';return}try{const d=await api('/api/admin/aliases/export',{method:'POST',body:JSON.stringify({emails})});for(const exported of d.items){const item=state.aliases.find(a=>a.email===exported.email);if(item){item.public_id=exported.public_id;item.exported_at=exported.exported_at;item.api_active=true}}selected.clear();render();const blob=new Blob([d.export_text+'\n'],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hme-customer-pages-'+new Date().toISOString().slice(0,10)+'.txt';a.click();URL.revokeObjectURL(url);showToken('已导出 '+d.items.length+' 条客户取件链接',d.export_text)}catch(e){$('notice').textContent=e.message}}
async function syncProfile(id){try{const d=await api('/api/admin/profiles/'+encodeURIComponent(id)+'/sync',{method:'POST'});$('notice').textContent='同步完成，新增 '+d.imported+' 封验证码邮件';load()}catch(e){$('notice').textContent=e.message}}async function inspectProfile(id){try{const d=await api('/api/admin/profiles/'+encodeURIComponent(id)+'/inspect',{method:'POST'});const messages=d.messages.map(m=>`UID ${m.uid} · ${m.status}\n${m.sender||'未知发件人'}\n${m.subject||'无标题'}\n${m.received_at||'无时间'}\n路由: ${Object.entries(m.routing).map(([k,v])=>k+': '+v).join(' | ')||'无'}\n匹配 HME: ${m.matched_aliases.join(', ')||'无'}${m.code?'\n验证码: '+m.code:''}`).join('\n\n')||'收件箱最近 20 封中没有可读取的邮件';showToken('最近收件（本次重新扫描新增 '+d.imported+' 封）',messages)}catch(e){$('notice').textContent=e.message}}async function saveRetention(){await api('/api/admin/settings/retention',{method:'POST',body:JSON.stringify({retention_days:+$('retentionDays').value})});$('notice').textContent='保留期已保存'}async function logout(){await api('/api/admin/logout',{method:'POST'});location='/login'}
$('profileForm').addEventListener('submit',async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/admin/profiles',{method:'POST',body:JSON.stringify(payload)});e.target.reset();presetChanged();load()}catch(err){$('notice').textContent=err.message}});presetChanged();load();
</script></body></html>"""
